"""Publish the frozen complete cohort only after both independent audits pass."""
import json,datetime
from pathlib import Path
from .boolean_classifier_common import OUT,sha,guard
from .fine_range_common import atomic_json

def main():
    p=json.loads((OUT/'protocol.json').read_text());guard(p);m=json.loads((OUT/'manifest.json').read_text());n=json.loads((OUT/'native_audit.json').read_text());s=json.loads((OUT/'statistics.json').read_text());a=json.loads((OUT/'statistics_audit.json').read_text())
    assert m['complete'] and n['passed'] and a['passed'];assert n['producer_manifest_sha256']==sha(OUT/'manifest.json') and a['statistics_sha256']==sha(OUT/'statistics.json')
    assert len(m['rows'])==len(n['rows'])==300 and m['native_updates']==n['native_updates']==609168000000
    lines=['# Full learned Boolean classifier at equal active-update budgets','','Five fixed positive-weight MNIST64->32->10 models; complete10000-image previously consumed test set; ten Monte Carlo seeds per model/method/budget. All2368 weights have one finite-field probability-programmed native THRML node. Both layers accumulate before ReLU/final readout. Biases remain deterministic. R1 reconstructs weights using counts and deterministic activations; R3 samples activation nodes and accumulates integer AND/column counts with affine correction for negative inputs. F64 host readout is external arithmetic, not physical AND circuitry.','','## All sampling budgets','','Accuracy is averaged across individual stochastic runs, not an ensemble of averaged logits. Five starting models remain five model-level units.','','| Regime | Samples/layer | Mean accuracy (%) | Mean cross entropy (nats) |','|---|---:|---:|---:|']
    for r in s['summaries']:lines.append(f"| {r['regime']} | {r['T']} | {100*r['mean_accuracy']:.4f} | {r['mean_cross_entropy']:.8f} |")
    lines+=['','## Deterministic controls','','| Condition | Mean accuracy (%) | Mean cross entropy |','|---|---:|---:|']
    for name,v in s['baseline_summary'].items():lines.append(f'| {name} | {100*v[0]:.4f} | {v[1]:.8f} |')
    lines+=['','FP32_weights_F64_readout applies stored FP32 weights through the same F64 readout convention; stored_FP32_reference preserves the earlier model outputs. Uniform INT2/4/8 controls dequantize weights on[0,1] and use F64 software, not optimized integer kernels. Programmed-mean R1/R3 plug-in controls are not expectations of a nonlinear stochastic network.','','## All paired contrasts','','Intervals are descriptive hierarchical5000-draw bootstrap sensitivity: resample five model IDs, then ten paired MC seed IDs within each selected model. All test images stay fixed. These consumed data cannot supply fresh generalization confirmation. No quality rule is invented after outcomes.','','| Contrast | Budget index | Accuracy difference (pp),95% interval | CE difference,95% interval |','|---|---:|---|---|']
    for c in s['contrasts']:
        d=c['difference'];ci=c['descriptive_95_interval'];lines.append(f"| {c['contrast']} | {c['budget_index']} | {100*d[0]:.4f} [{100*ci[0][0]:.4f}, {100*ci[0][1]:.4f}] | {d[1]:.8f} [{ci[1][0]:.8f}, {ci[1][1]:.8f}] |")
    clipping=sum(r['hidden_clipped_coordinates'] for r in m['rows']);inputclip=max(r['input_outside_requested_range'] for r in m['rows'])
    lines+=['','## Audit and resources','',f"Every count, derived second-layer activation code and final causal logit of all300 cases is independently reproduced with public raw-state sampling. Independent statistics checks300 case metrics,35 deterministic model baselines and90000 bootstrap values. Production609,168,000,000 plus independent replay609,168,000,000 native scheduled updates. Separate bounded preflight costs are retained in their own reports.",'','R1 evaluates2368 weight nodes/round; R3 evaluates2368 weight plus768 activation nodes/round for banks of eight inputs. Sample schedules[98,392,1568] versus[74,296,1184] give exactly equal full-forward active updates. Software vectorization is repeated inference queries, not asserted physical replicas. Activation programming, nominal controller/range storage, readout arithmetic, idle behavior and sampling rounds remain separate costs.',f'','Hidden activation ranges are fixed from validation data with25% safety margin. R3 hidden coordinates clipped across the entire cohort: {clipping}; input coordinates outside the shared validation range per full test pass: {inputclip}. All finite8-bit field controls are bounded±4 and free; exact0/1 probabilities are approximated, not clamped.','',p['scope'],'','The stationary probability encoding remains established. This result does not establish physical energy, latency, controller area or broader-model superiority. Earlier failures remain unchanged and the long-horizon goal remains active.']
    report=Path('results/thrml_spw/BOOLEAN_CLASSIFIER_REPORT.md');report.write_text('\n'.join(lines)+'\n')
    artifacts=[OUT/n for n in ['protocol.json','manifest.json','native_audit.json','statistics.json','statistics_audit.json','baseline_logits.npz','statistical_arrays.npz']]+[report]
    for r in m['rows']:assert sha(r['path'])==r['sha256']
    atomic_json(OUT/'completion.json',{'status':'completed_and_independently_audited_goal_active','recorded_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'cases':300,'production_updates':m['native_updates'],'independent_replay_updates':n['native_updates'],'new_heldout_confirmation':False,'physical_systems_advantage_proven':False,'artifact_sha256':{str(x):sha(x) for x in artifacts},'all_case_hashes_verified_again':True});print('Full classifier report completed and independently audited; broader goal active',flush=True)
if __name__=='__main__':main()
